import{z as l,x as i,o as A,c as p,q as r,j as s,D as B,d as a,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"生命周期治理收束","description":"","frontmatter":{"title":"生命周期治理收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-map.md","filePath":"quant/sl-map.md","lastUpdated":1791413859000}'),d={name:"quant/sl-map.md"};function D(m,E,h,C,F,u){const t=i("Mermaid");return A(),p("div",null,[E[2]||(E[2]=r('<h1 id="生命周期治理收束" tabindex="-1">生命周期治理收束 <a class="header-anchor" href="#生命周期治理收束" aria-label="Permalink to &quot;生命周期治理收束&quot;">​</a></h1><div class="epigraph"><p>治理做得好不好，只在两处现形：钱停得下来的时候，和理由查得到的时候。</p><footer>—— 据 Federal Reserve SR 11-7（2011）与本课程各课口径整理</footer></div><p><a href="/quant/sl-team-cases">上一课</a>把规则绑定到岗位与节奏，三个案例走完了从立项到退役的全流程。本课程到此收束：本课把九课收成一张图与一组不变量，交代哪些部分刻意留给了相邻课程。判据怎么设、监测怎么听，是主干课与风险课的对象；本课程回答的始终是治理面——策略从想法到退役，每一步凭什么、谁批准、记在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的问题是：九课合起来，治理到底保证了什么？答案不是「策略更赚钱」——治理不创造 alpha，判据不过就是不进。治理保证的是一组<strong>可回答性</strong>：这个仓位此刻凭什么在跑（台账与审批）、它最多能跑多大（容量）、它预期还剩多少（衰减带）、它碰没碰红线（合规门）、停了之后怎么出来（退出）、死了之后留下什么（知识）。这些问题的答案必须在任何时刻都可查、可审计、可复现——这就是治理的全部产出，也是它区别于经验管理的地方。</p><p><span class="marginnote">术语翻译：治理里的「可回答性」指任何时刻都能凭台账回答——这个仓位凭什么在跑、最多跑多大、预期还剩多少、停了怎么出来。注意治理不回答「赚不赚钱」：它保证问题有据可查，alpha 本身仍要靠研究去挣。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把九课折成一条主线：<strong>台账</strong>立状态机与指针链；<strong>版本与审批</strong>填「凭什么进」，判据挂边、有效挑战；<strong>容量</strong>填「跑多大」，声明三层、扩容即版本；<strong>衰减</strong>填「还剩多少」，预算预扣、三档动作；<strong>合规</strong>立独立于判据的门，输出进执行层；<strong>退出</strong>预写分级、退役有硬定义；<strong>知识</strong>让每一次死亡可检索、\\(N\\) 不清零；<strong>团队</strong>给全部规则配岗位、节奏与默认动作。贯穿九课的不变量七条：追加不改写；单一事实来源；监测只读；判据挂边不挂人；\\(N\\) 永不清零；实盘仓位必可沿指针链反查；退出预写。</p><p><span class="marginnote">直觉类比：七条不变量像账房的规矩而不是师傅的手艺——师傅可以换，规矩不能改。任何一条被临时豁免，对应的失效模式就自动开门：能改写的历史就能被重写，能清零的 \\(N\\) 就能让死信号复活。</span></p>',9)),(A(),s(o,null,{default:B(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E7%A0%94%E7%A9%B6%EF%BC%9A%E5%88%A4%E6%8D%AE%E4%B8%8E%20N%22%5D%20--%3E%20APR%5B%22%E7%89%88%E6%9C%AC%E4%B8%8E%E5%AE%A1%E6%89%B9%EF%BC%9A%E6%9C%89%E6%95%88%E6%8C%91%E6%88%98%22%5D%0A%20%20APR%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E5%A3%B0%E6%98%8E%E4%B8%8E%E5%88%86%E6%A1%A3%E6%89%A9%E5%AE%B9%22%5D%0A%20%20CAP%20--%3E%20LIVE%5B%22%E5%AE%9E%E7%9B%98%EF%BC%9A%E7%9B%91%E6%B5%8B%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20LIVE%20--%3E%20DEC%5B%22%E8%A1%B0%E5%87%8F%E5%B8%A6%E4%B8%89%E6%A1%A3%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20DEC%20--%3E%20EXIT%5B%22%E9%80%80%E5%87%BA%E6%9C%BA%E5%88%B6%EF%BC%9A%E9%A2%84%E5%86%99%E5%88%86%E7%BA%A7%22%5D%0A%20%20EXIT%20--%3E%20KM%5B%22%E7%9F%A5%E8%AF%86%E6%B2%89%E6%B7%80%EF%BC%9A%E5%8D%B7%E5%AE%97%E4%B8%8E%E5%A4%B1%E8%B4%A5%E5%BA%93%22%5D%0A%20%20KM%20--%3E%20RES%0A%20%20COMP%5B%22%E5%90%88%E8%A7%84%E9%97%A8%EF%BC%9A%E4%B8%8A%E7%BA%BF%E5%89%8D%E3%80%81%E5%91%A8%E6%9C%9F%E3%80%81%E4%BA%8B%E4%BB%B6%22%5D%20-.-%3E%20APR%0A%20%20COMP%20-.-%3E%20LIVE%0A%20%20TEAM%5B%22%E8%A7%92%E8%89%B2%E3%80%81%E8%8A%82%E5%A5%8F%E4%B8%8E%E9%BB%98%E8%AE%A4%E5%8A%A8%E4%BD%9C%22%5D%20-.-%3E%20DEC%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("不变量为什么是这七条：每一条都堵一个已知的失效模式。追加不改写堵历史重写——审计要求昨天批准过的东西今天还查得到原样；单一事实来源堵清单漂移——两份清单等于没有清单；监测只读堵球门移动——穿带后的任何改动都是新试验；判据挂边堵人治——批准是核对不是恩典；\\(N\\) 不清零堵多重检验复活——换包装不算新信号；指针链反查堵黑箱持仓——答不出「凭什么」的仓位按违规处置；退出预写堵临场偏晚——把推迟退出变成需要明说的动作。七条合起来的机制是一个：让「治理失效」在失效发生的时刻就被发现，而不是在亏损或问询到来时才暴露。SR 11-7 的相称性原则在此收尾：门的深度随策略的规模与复杂度调节，小策略走窄门，但"),e("strong",null,"没有免门的政策"),a("——相称性调节强度，不删除义务。")],-1)),(A(),s(o,null,{default:B(()=>[n(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20F1%5B%22%E5%8E%86%E5%8F%B2%E9%87%8D%E5%86%99%22%5D%20--%3E%20I1%5B%22%E8%BF%BD%E5%8A%A0%E4%B8%8D%E6%94%B9%E5%86%99%22%5D%0A%20%20F2%5B%22%E6%B8%85%E5%8D%95%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20I2%5B%22%E5%8D%95%E4%B8%80%E4%BA%8B%E5%AE%9E%E6%9D%A5%E6%BA%90%22%5D%0A%20%20F3%5B%22%E7%90%83%E9%97%A8%E7%A7%BB%E5%8A%A8%22%5D%20--%3E%20I3%5B%22%E7%9B%91%E6%B5%8B%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20F4%5B%22%E4%BA%BA%E6%B2%BB%E6%89%B9%E5%87%86%22%5D%20--%3E%20I4%5B%22%E5%88%A4%E6%8D%AE%E6%8C%82%E8%BE%B9%E4%B8%8D%E6%8C%82%E4%BA%BA%22%5D%0A%20%20F5%5B%22%E5%A4%9A%E9%87%8D%E6%A3%80%E9%AA%8C%E5%A4%8D%E6%B4%BB%22%5D%20--%3E%20I5%5B%22N%20%E6%B0%B8%E4%B8%8D%E6%B8%85%E9%9B%B6%22%5D%0A%20%20F6%5B%22%E9%BB%91%E7%AE%B1%E6%8C%81%E4%BB%93%22%5D%20--%3E%20I6%5B%22%E4%BB%93%E4%BD%8D%E6%B2%BF%E6%8C%87%E9%92%88%E9%93%BE%E5%8F%8D%E6%9F%A5%22%5D%0A%20%20F7%5B%22%E4%B8%B4%E5%9C%BA%E5%81%8F%E6%99%9A%22%5D%20--%3E%20I7%5B%22%E9%80%80%E5%87%BA%E9%A2%84%E5%86%99%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">自检只需三个问题：随机挑一个实盘仓位，五分钟能否答出它凭什么在跑？随机挑一个已退役策略，能否查到它死于哪条判据、第几次试验？随机挑一条硬限额，能否确认它此刻在执行层生效？三个「能」，就是本课程全部内容的落地测试。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程刻意没有覆盖的三块，都在知识树的紧邻位置：数据管线与版本化是量化数据工程课的对象，本课只引用其哈希；回测与成交模拟是回测框架课的对象，判据的数字从那里来；多人协作、代码评审与委员会流程的工程细节是研究协作课的对象，本课只定了职责边界。治理本身也有成本：每道门都消耗研究速度，门无限多则组织瘫痪——这正是相称性原则存在的理由。最后一点边界要说诚实：治理的输出是「可回答」与「可停」，不是「一定赚」；台账记得再干净，救不了一个没有 alpha 的信号——判据与统计，仍然是一切的前一课。</p><p><span class="marginnote">为什么重要：相称性原则容易被读成「小策略可以免手续」。恰恰相反——它只调节门的深浅，不删除门本身。一旦允许「这次太小、跳过审批」，豁免先例本身就成了新漏洞，之后每个策略都会「刚好」够小。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>九课一条主线：台账、版本与审批、容量、衰减、合规、退出、知识、团队，各答一个可回答性问题。</li><li>七条不变量贯穿全程：追加不改写、单一来源、监测只读、判据挂边、\\(N\\) 不清零、仓位可反查、退出预写。</li><li>相称性原则收尾：门的深度随规模与复杂度调节，不删除义务。</li><li>本课程的落地测试是三个「五分钟能否答出」；治理保证可回答与可停，不保证赚钱。</li><li>出处：治理框架据 Federal Reserve SR 11-7（2011）整理；衰减证据见 McLean–Pontiff, <em>JF</em>, 2016；容量口径见<a href="/quant/strategy-capacity-decay">策略容量与衰减</a>；监测与复盘分别见<a href="/quant/live-drift-monitor">实盘漂移监测</a>与<a href="/quant/research-postmortem">研究复盘</a>。</li></ul>',6))])}const f=l(d,[["render",D]]);export{g as __pageData,f as default};
